styles:
.reader-quote {
  font-style: normal;
  color: #cc7722;
  border-left: 3px solid #cc7722;
  padding-left: 6px;
  font-weight: 500;
}
.reader-ellipsis {
  letter-spacing: 6px;
  color: #aa6611;
  opacity: 0.6;
}
.reader-dash {
  letter-spacing: 3px;
  color: #8b4513;
  font-weight: 700;
}
.reader-speak {
  color: #d4a017;
  font-weight: 700;
}
.reader-body :deep(.reader-dropcap) {
  float: left;
  font-size: 3.4em;
  line-height: 0.7;
  padding-right: 8px;
  padding-top: 4px;
  color: #cc7722;
  font-weight: 900;
  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.5);
  font-family: 'Impact', 'Arial Black', sans-serif;
}
